import { spawnSync } from 'node:child_process';
import { EXECUTABLE_PATH } from './constants.mjs';

export function runExecutable(rawArgs) {
  const result = spawnSync(EXECUTABLE_PATH, rawArgs, {
    stdio: 'inherit',
  });

  if (result.error) {
    return {
      exitCode: 1,
      error: result.error,
    };
  }

  return {
    exitCode: result.status ?? 1,
    error: null,
  };
}

function isDigit(character) {
  return character >= '0' && character <= '9';
}

function isAsciiLetter(character) {
  return (
    (character >= 'a' && character <= 'z') ||
    (character >= 'A' && character <= 'Z')
  );
}

function isNegativeNumberLike(token) {
  if (token.length < 2 || token[0] !== '-') {
    return false;
  }

  let index = 1;
  let sawDigit = false;
  let sawDot = false;

  if (token[index] === '.') {
    sawDot = true;
    index += 1;
  }

  while (index < token.length) {
    const character = token[index];
    if (isDigit(character)) {
      sawDigit = true;
      index += 1;
      continue;
    }

    if (character === '.' && !sawDot) {
      sawDot = true;
      index += 1;
      continue;
    }

    return false;
  }

  return sawDigit;
}

function looksLikeOptionToken(token) {
  if (token === undefined || token.length === 0) {
    return false;
  }

  if (token === '--') {
    return true;
  }

  if (token === '-') {
    return false;
  }

  if (isNegativeNumberLike(token)) {
    return false;
  }

  if (!token.startsWith('-')) {
    return false;
  }

  if (token.startsWith('--')) {
    return true;
  }

  return isAsciiLetter(token[1]);
}

function valueLooksLikeMissingArgument(token) {
  if (token === undefined) {
    return true;
  }

  return looksLikeOptionToken(token);
}

export function parseCommandLine(argv) {
  let sawA = false;
  let positionalMode = false;
  const extras = [];

  for (let index = 0; index < argv.length; index += 1) {
    const token = argv[index];

    if (positionalMode) {
      extras.push(token);
      continue;
    }

    if (token === '-h' || token === '--help') {
      return {
        kind: 'help',
      };
    }

    if (token === '--') {
      positionalMode = true;
      extras.push(token);
      continue;
    }

    if (token === '--a') {
      const value = argv[index + 1];
      if (valueLooksLikeMissingArgument(value)) {
        return {
          kind: 'error',
          message: 'argument --a: expected one argument',
        };
      }

      sawA = true;
      index += 1;
      continue;
    }

    if (token.startsWith('--a=')) {
      sawA = true;
      continue;
    }

    extras.push(token);
  }

  if (!sawA) {
    return {
      kind: 'error',
      message: 'the following arguments are required: --a',
    };
  }

  if (extras.length > 0) {
    return {
      kind: 'error',
      message: `unrecognized arguments: ${extras.join(' ')}`,
    };
  }

  return {
    kind: 'run',
  };
}

import process from 'node:process';
import { parseCommandLine } from './lib/args.mjs';
import { writeStderr, writeStdout } from './lib/io.mjs';
import { formatError, formatHelp } from './lib/messages.mjs';
import { runExecutable } from './lib/process_runner.mjs';

const rawArgs = process.argv.slice(2);
const parsed = parseCommandLine(rawArgs);

if (parsed.kind === 'help') {
  writeStdout(formatHelp());
  process.exit(0);
}

if (parsed.kind === 'error') {
  writeStderr(formatError(parsed.message));
  process.exit(2);
}

const result = runExecutable(rawArgs);

if (result.error !== null) {
  writeStderr(`${result.error.message}\n`);
}

process.exit(result.exitCode);
